import {startAuth} from './auth-ui.js';
import {apparatusKinds,newSandbox,fitSandbox,zoomSandbox,normaliseSandbox,moveLabObject,nearestVessel,tickSandbox,sandboxStageHTML,attachSandbox} from './sandbox.js';
import {extraToolsHTML,mountExtraTools} from './extra-tools.js';
import {chemicals,elements} from './data.js';
import {makeVessel,dose,resolve,appearance,ph,transfer,filterVessel,evaporate,gasTests,balance,parseFormula,molarMass,salt,cations,anions} from './chemistry.js';
import {lessons,practicals,specURL,testCases} from './curriculum.js';
import {esc,fmt,chemText,icon,glassware,date} from './ui.js';
import {defaults,simulate,controlHTML,stageHTML,graphHTML,controls} from './simulations.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let KEY='chemlab.studio.v2';
const NAV=[['bench','Lab bench'],['practicals','Practicals'],['learn','Learn & practise'],['periodic','Periodic table'],['tools','Calculations'],['notebook','Lab notebook']];
let storageOK=true;
function fresh(){const v=makeVessel(1);return {version:2,vessels:[v,makeVessel(2,'flask')],sandbox:newSandbox(),selected:1,nextVessel:3,notes:[],mastered:[],practised:[],trials:{},params:{},theme:'light',motion:false,score:{correct:0,total:0}};}
function validate(data){
 if(!data||data.version!==2||!Array.isArray(data.vessels)||data.vessels.length>24)throw Error('This is not a Chemlab 2 workspace.');
 const str=(x,n=2000)=>typeof x==='string'&&x.length<=n;
 const num=(x,min,max)=>typeof x==='number'&&Number.isFinite(x)&&x>=min&&x<=max;
 const ids=new Set();
 for(const v of data.vessels){
  if(!num(v.id,1,1e6)||ids.has(v.id)||!['beaker','flask','tube','dish'].includes(v.shape)||!str(v.name,80)||!num(v.capacity,1,500)||!num(v.volume,0,v.capacity)||!num(v.temp,0,1000)||!Array.isArray(v.contents)||v.contents.length>150||!Array.isArray(v.events)||v.events.length>200)throw Error('Invalid vessel data.');ids.add(v.id);
  for(const s of v.contents){const c=s.chem;if(!num(s.n,0,1000)||!c||!str(c.id,100)||!str(c.name,120)||!str(c.formula,80)||!/^#[a-f0-9]{6}$/i.test(c.color)||!['solid','aqueous','liquid','gas'].includes(c.state))throw Error('Invalid chemical data.');const known=chemicals.find(k=>k.id===c.id);if(known){s.chem={...known,state:c.state};}else if(c.id.startsWith('salt:')&&cations[c.cation]&&anions[c.anion]){s.chem={...salt(c.cation,c.anion),state:c.state};}else if(!/^product:[A-Za-z0-9()]+$/.test(c.id))throw Error('Unknown chemical in workspace.');}
  v.events=v.events.map(e=>{if(!str(e.text)||!str(e.time,80))throw Error('Invalid event.');return {time:e.time,text:e.text,type:str(e.type,40)?e.type:'note',kind:str(e.kind,100)?e.kind:undefined,equation:str(e.equation,500)?e.equation:undefined,heat:str(e.heat,50)?e.heat:undefined,limiting:str(e.limiting,200)?e.limiting:undefined};});
  const gas={};for(const [k,n]of Object.entries(v.gas||{})){if(!/^[A-Za-z0-9]{1,20}$/.test(k)||!num(n,0,1000))throw Error('Invalid gas data.');gas[k]=n;}v.gas=gas;
  v.waterVolume=num(v.waterVolume,0,v.volume)?v.waterVolume:v.volume;v.waterConsumed=num(v.waterConsumed,0,1000)?v.waterConsumed:0;v.heated=Boolean(v.heated);if(v.indicator&&!chemicals.some(c=>c.id===v.indicator&&c.category==='indicator'))delete v.indicator;
 }
 if(!Array.isArray(data.notes)||data.notes.length>100||data.notes.some(n=>!str(n.id,80)||!/^[A-Za-z0-9_-]+$/.test(n.id)||!str(n.title,200)||!str(n.body,100000)||!str(n.date,80)))throw Error('Invalid notebook data.');
 data.mastered=Array.isArray(data.mastered)?data.mastered.filter(i=>lessons.some(l=>l.id===i)):[];data.practised=Array.isArray(data.practised)?data.practised.filter(i=>practicals.some(p=>p.id===i)):[];
 const params={};for(const [id,list]of Object.entries(controls)){params[id]=defaults(id);for(const c of list){const v=data.params?.[id]?.[c.key];if(num(v,c.options?0:c.min,c.options?c.options.length-1:c.max))params[id][c.key]=v;}}
 data.params=params;
 const trials={};for(const p of practicals){const t=data.trials?.[p.id];if(Array.isArray(t))trials[p.id]=t.slice(-50).filter(t=>str(t.date,80)&&Array.isArray(t.metrics)&&t.metrics.length<=10&&t.metrics.every(a=>Array.isArray(a)&&a.length===2&&a.every(v=>str(v,1000)))).map(t=>({date:t.date,metrics:t.metrics,params:Object.fromEntries(controls[p.id].map(c=>[c.key,num(t.params?.[c.key],c.options?0:c.min,c.options?c.options.length-1:c.max)?t.params[c.key]:c.value]))}));}data.trials=trials;
 data.nextVessel=Math.max(0,...ids)+1;data.selected=ids.has(data.selected)?data.selected:data.vessels[0]?.id;data.theme=data.theme==='dark'?'dark':'light';data.motion=Boolean(data.motion);data.score={correct:Math.max(0,Math.min(Number(data.score?.correct)||0,100000)),total:Math.max(0,Math.min(Number(data.score?.total)||0,100000))};normaliseSandbox(data);return data;
}
let state;try{const raw=localStorage.getItem(KEY);state=raw?validate(JSON.parse(raw)):fresh();}catch{state=fresh();storageOK=false;}
let benchShelfTab='reagents';
let page='bench',practicalID=null,lessonID=lessons[0].id,noteID=state.notes[0]?.id,filter='',catalogFilter='All',shelfQuery='',shelfFilter='All',elementQuery='',elementFilter='All',undo=[],compare=null,quiz=null,quizIndex=0,quizRevealed=false,quizOptions=[],timer=null;
const main=$('#main'),dialog=$('#dialog');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#save-status').textContent='Saved on this device';}catch{storageOK=false;$('#save-status').textContent='Storage unavailable · export a backup';}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function applySettings(){document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('reduce-motion',state.motion);}
function checkpoint(){undo.push(JSON.stringify({vessels:state.vessels,sandbox:state.sandbox}));if(undo.length>20)undo.shift();}
function selected(){return state.vessels.find(v=>v.id===state.selected)||state.vessels[0];}
function mutate(fn){const before=JSON.stringify({vessels:state.vessels,sandbox:state.sandbox});try{checkpoint();fn();save();render();}catch(e){const old=JSON.parse(before);state.vessels=old.vessels;state.sandbox=old.sandbox;undo.pop();toast(e.message);}}
function download(name,content,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function closeInlinePanel(){dialog.hidden=true;dialog.open=false;const content=$('#dialog-content');if(content)content.innerHTML='';}
function modal(title,html){const host=page==='bench'?$('#bench-controls'):$('#inline-host');if(host?.appendChild)host.appendChild(dialog);$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-btn" data-act="close" aria-label="Close details">×</button></div><div class="dialog-body">${html}</div>`;dialog.hidden=false;dialog.open=true;}
function formModal(title,body,onSubmit){modal(title,`<form id="modal-form" class="dialog-form">${body}<div class="dialog-actions"><button class="btn" type="button" data-act="close">Cancel</button><button class="btn primary" type="submit">Confirm</button></div></form>`);$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSubmit(new FormData(e.currentTarget));closeInlinePanel();save();render();}catch(e){toast(e.message);}};}
const field=(name,label,value,type='number',extra='')=>`<div class="field"><label for="field-${name}">${esc(label)}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
function heading(title,subtitle,extra='',eyebrow='A LITTLE CURIOSITY GOES A LONG WAY'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${extra}</div>`;}
function render(){closeInlinePanel();applySettings();document.body.classList.toggle('is-sandbox',page==='bench');normaliseSandbox(state);$('#nav').innerHTML=NAV.map(([id,label])=>`<button class="nav-btn ${page===id?'active':''}" data-act="nav" data-id="${id}" ${page===id?'aria-current="page"':''}>${icon(id)}<span class="nav-label">${label}</span>${id==='practicals'?'<span class="count">18</span>':''}</button>`).join('');$('#crumb').textContent=NAV.find(([id])=>id===page)?.[1]||'Lab bench';
 if(page==='bench')renderBench();if(page==='practicals')practicalID?renderPractical():renderPracticals();if(page==='learn')quiz?renderQuiz():renderLearn();if(page==='periodic')renderPeriodic();if(page==='tools')renderTools();if(page==='notebook')renderNotebook();
 if(!storageOK)$('#save-status').textContent='Export a backup to keep your work';}
function practicalCard(p){const colors={Principles:'#79abd7',Inorganic:'#6fc0b6',Physical:'#ac9dd4',Organic:'#d4b185'};return `<button class="practical-card" style="--card-color:${colors[p.strand]}" data-act="practical" data-id="${p.id}"><div class="category">${esc(p.strand.toUpperCase())} <span class="badge" style="margin-left:8px">${esc(p.ref)}</span></div><div class="card-art">${glassware(p.id==='titration'?'flask':p.id==='analysis'?'tube':'beaker',colors[p.strand],.45,'#edf3f5',p.id==='precipitation')}</div><h3>${esc(p.title)}</h3><p>${esc(p.headline)}</p><div class="card-foot"><span>${state.practised.includes(p.id)?'✓ Explored':'Explore practical'}</span><span class="arrow">↗</span></div></button>`;}
function renderBench(){
 const v=selected();
 main.innerHTML=heading('Make room for discovery.','A free bench for your own experiments. Arrange, connect, measure, and explore.',`<div class="row"><button class="btn subtle" data-act="export">↗ Save workspace</button><button class="btn primary" data-act="add-vessel">＋ Add apparatus</button></div>`,'THE SANDBOX LAB')+`
 <div class="bench-layout sandbox-layout"><section class="panel glass shelf sandbox-shelf"><div class="panel-head"><h2>Library</h2></div><div class="shelf-tabs"><button data-act="shelf-tab" data-id="reagents" class="${benchShelfTab==='reagents'?'active':''}">Reagents <span>122</span></button><button data-act="shelf-tab" data-id="apparatus" class="${benchShelfTab==='apparatus'?'active':''}">Apparatus</button></div><div class="shelf-search"><input id="shelf-search" class="search" aria-label="Search the shelf" placeholder="${benchShelfTab==='reagents'?'Search name or formula…':'Search apparatus…'}" value="${esc(shelfQuery)}"></div>${benchShelfTab==='reagents'?`<div class="chips">${['All','Acids','Bases','Salts','Metals','More'].map(c=>`<button class="chip ${shelfFilter===c?'active':''}" data-act="shelf-filter" data-id="${c}">${c}</button>`).join('')}</div>`:''}<div class="reagents" id="reagents"></div><div class="shelf-foot">Drag an item onto the bench, or tap to add it. Drop reagents into empty space to place a bottle.</div></section>
 <div class="bench-center"><section class="panel glass sandbox-scene"><div class="sandbox-toolbar"><div><h2>Workspace</h2></div><div class="row"><button class="btn small" data-act="sandbox-home">Centre scene</button><button class="btn small danger" data-act="clear-bench">Clear bench</button></div></div>${sandboxStageHTML(state,elements)}</section><div class="glass panel bench-actions">${[['heat','Heat'],['transfer','Transfer'],['filter','Filter'],['crystallise','Crystallise'],['evaporate','Evaporate'],['gas-test','Gas test'],['history','History'],['undo','Undo']].map(([id,label])=>`<button class="btn" data-act="${id}" ${(id==='undo'?!undo.length:!v)?'disabled':''}><span class="tool-icon">${icon(id)}</span>${label}</button>`).join('')}</div><div class="sandbox-note"><span class="live-dot"></span><span>Bring compatible parts together to snap. Pull a part away to detach. Set measured additions on the right.</span><button data-act="sandbox-help">How to use ↗</button></div></div>
 <section class="panel glass inspector sandbox-inspector"><div class="panel-head"><h2>Under the surface</h2><span class="badge">Selected vessel</span></div><div class="panel-body"><div id="measurement-controls"></div><div id="bench-controls"></div><div id="inspector"></div></div></section></div>`;
 renderShelf();renderMeasurementControls();renderInspector();const viewport=$('#sandbox-viewport');if(!state.sandbox.fitted&&viewport?.clientWidth){fitSandbox(state,viewport.clientWidth,viewport.clientHeight);$('#sandbox-world').style.transform=`translate(${state.sandbox.panX}px,${state.sandbox.panY}px) scale(${state.sandbox.zoom})`;save();}$('#shelf-search').oninput=e=>{shelfQuery=e.target.value;renderShelf();};
 attachSandbox(state,{save,checkpoint,render,onDose:id=>{try{toast(directBenchDose(id));save();render();}catch(error){toast(error.message);}},onAddReagent:sandboxDrop,onSelect:()=>renderInspector(),onObjectDrop:applyDirectDrop,onError:toast});
}
function renderShelf(){if(benchShelfTab==='apparatus'){
 const list=[...['beaker','flask','tube','dish'].map(kind=>({id:'vessel:'+kind,name:{beaker:'Beaker',flask:'Conical flask',tube:'Test tube',dish:'Evaporating dish'}[kind],kind})),...Object.entries(apparatusKinds).filter(([kind])=>kind!=='bottle').map(([kind,spec])=>({id:'apparatus:'+kind,name:spec.name,kind}))].filter(item=>item.name.toLowerCase().includes(shelfQuery.toLowerCase()));
 $('#reagents').innerHTML=list.map(item=>`<button class="equipment-shelf-item" draggable="true" data-act="shelf-add" data-id="${item.id}"><span class="equipment-glyph">${icon(['beaker','flask','tube','dish'].includes(item.kind)?'bench':item.kind==='burner'?'heat':item.kind==='funnel'?'filter':item.kind==='stopwatch'?'history':'tools')}</span><span><b>${item.name}</b><small>Drag to place · tap to add</small></span><span>＋</span></button>`).join('')||'<div class="empty">No matching apparatus.</div>';
 $$('.equipment-shelf-item').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.id));return;
 }const cat={Acids:'acid',Bases:'base',Salts:'salt',Metals:'metal'},q=shelfQuery.toLowerCase().trim();const list=chemicals.filter(c=>(!q||(c.name+' '+c.formula).toLowerCase().includes(q))&&(shelfFilter==='All'||(shelfFilter==='More'?!['acid','base','salt','metal'].includes(c.category):c.category===cat[shelfFilter])));$('#reagents').innerHTML=list.map(c=>`<button draggable="true" class="reagent" data-act="dose" data-id="${c.id}"><span class="bottle-icon" style="--chem:${c.color}"></span><span><b>${esc(c.name)}</b><small>${chemText(c.formula)} · ${c.state==='aqueous'?'solution':esc(c.state)}</small></span><span class="plus">＋</span></button>`).join('')||'<div class="empty">No reagents found.</div>';$$('.reagent').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.id));}
function renderInspector(){const item=apparatusItem(state.sandbox.selectedItem);if(item){renderApparatusInspector(item);return;}const v=selected();if(!v){$('#inspector').innerHTML='<div class="empty">Add and select a vessel to inspect it.</div>';return;}const a=appearance(v),p=a.ph;
 $('#inspector').innerHTML=`<div><div class="metric-pair"><div class="metric"><label>VOLUME</label><strong>${fmt(v.volume)} <small>mL</small></strong></div><div class="metric"><label>MODEL pH</label><strong>${p===null?'—':fmt(p,2)}</strong></div></div><div class="mini-label">${esc(v.name)} · contents</div>${v.contents.map(s=>`<div class="content-line"><span class="dot" style="--chem:${s.chem.color}"></span><div>${esc(s.chem.name)}<br><small>${chemText(s.chem.formula)} · ${s.n.toExponential(2)} mol · ${s.chem.state==='aqueous'?'aq':s.chem.state}</small></div></div>`).join('')||`<div class="hint">${v.volume?'Solvent only.':'Clean glass. Endless possibilities.'}</div>`}${v.indicator?`<div class="hint" style="margin-top:8px">Indicator: ${esc(chemicals.find(c=>c.id===v.indicator)?.name)}</div>`:''}<div class="hint" style="margin-top:10px">${p===null?'pH is unavailable for dry solids or mixtures outside the supported acid–base model.':'Ideal concentration model at 25°C. Salt hydrolysis and non-ideal activities are limited; see model notes.'}</div></div><div><div class="mini-label">Latest reaction</div>${a.last?`<div class="reaction-box"><span class="badge">${esc(a.last.kind)}</span><div class="equation">${chemText(a.last.equation)}</div>${esc(a.last.text)}${a.last.limiting?`<div class="hint" style="margin-top:8px">Consumed: ${esc(a.last.limiting)}</div>`:''}</div>`:'<div class="reaction-box">Add a second substance and see what the supported chemistry predicts.</div>'}<div class="mini-label">Gas collected (ideal RTP)</div><div class="hint">${Object.entries(v.gas).map(([g,n])=>`${chemText(g)}: ${fmt(n*24000)} mL`).join(' · ')||'No gas recorded.'}</div><div class="inspector-actions"><button class="btn small" data-act="record-bench">＋ Notebook</button><button class="btn small" data-act="rename-vessel">Rename</button><button class="btn small danger" data-act="empty-vessel">Empty</button><button class="btn small danger" data-act="remove-vessel">Remove</button></div></div>`;
}
function doseDialog(id){const c=chemicals.find(c=>c.id===id),v=selected();if(!c)return;if(!v){toast('Add a vessel first.');return;}
 const liquid=['aqueous','liquid'].includes(c.state);formModal('A measured addition',`<div class="row"><span class="bottle-icon" style="--chem:${c.color}"></span><div><h3>${esc(c.name)}</h3><span class="muted">${chemText(c.formula)} · ${esc(c.state)}</span></div></div><p class="hint">Into ${esc(v.name)} · ${fmt(v.capacity-v.volume)} mL capacity available.<br>${esc(c.hazard||'Standard laboratory precautions apply.')} This is a virtual representation.</p>${field('amount',liquid?'Volume / mL':c.state==='gas'?'Gas volume at RTP / mL':'Mass / g',c.category==='indicator'?.1:liquid?state.sandbox.dosing.volume:c.state==='gas'?state.sandbox.dosing.gas:state.sandbox.dosing.mass,'number','min="0.001" max="1000" step="any" required')}${c.state==='aqueous'&&c.category!=='indicator'?field('concentration','Concentration / mol dm⁻³',state.sandbox.dosing.concentration,'number','min="0.001" max="2" step="any" required'):''}<p class="hint">Supported reactions resolve on addition. Unrecognised combinations are retained; no reaction prediction is made.</p>`,f=>{checkpoint();try{dose(v,c,Number(f.get('amount')),Number(f.get('concentration')||.1),elements);}catch(e){undo.pop();throw e;}});
}
function renderPracticals(){const list=practicals.filter(p=>(catalogFilter==='All'||p.strand===catalogFilter)&&(p.title+' '+p.description+' '+p.ref).toLowerCase().includes(filter.toLowerCase()));main.innerHTML=heading('Find your next “aha”.','18 interactive workspaces, from your first particles to your final practical.',`<span class="pill green">${state.practised.length} / 18 explored</span>`,'THE PRACTICAL COLLECTION')+`<div class="catalog-tools"><div class="chips">${['All','Principles','Inorganic','Physical','Organic'].map(c=>`<button class="chip ${catalogFilter===c?'active':''}" data-act="catalog-filter" data-id="${c}">${c}</button>`).join('')}</div><input id="catalog-search" class="search" placeholder="Search practicals or specification…" aria-label="Search practicals" value="${esc(filter)}"></div><div class="practical-grid" id="practical-grid">${list.map(practicalCard).join('')||'<div class="empty">No matching practicals.</div>'}</div>`;$('#catalog-search').oninput=e=>{filter=e.target.value;const pos=e.target.selectionStart;renderPracticals();$('#catalog-search').focus();$('#catalog-search').setSelectionRange(pos,pos);};}
function simParams(){return state.params[practicalID]||(state.params[practicalID]=defaults(practicalID));}
function renderPractical(){const p=practicals.find(p=>p.id===practicalID),params=simParams(),r=simulate(p.id,params);
 main.innerHTML=heading(p.title,p.description,`<button class="btn subtle" data-act="all-practicals">← All practicals</button>`,`${p.strand.toUpperCase()} · SPEC ${p.ref}`)+`<div class="practical-layout"><div><section class="panel glass"><div class="panel-head"><h2>${esc(p.headline)}</h2><span class="badge">Interactive model</span></div><div class="simulation-body"><div class="sim-stage" id="sim-stage">${stageHTML(p.id,params,r)}</div><div class="control-grid" id="sim-controls">${controlHTML(p.id,params)}</div><div class="sim-actions"><button class="btn primary" data-act="record-trial">＋ Record trial</button><button class="btn" data-act="reset-sim">Reset inputs</button>${r.points?'<button class="btn" data-act="compare">'+(compare?'Clear comparison':'Pin comparison')+'</button>':''}<button class="btn subtle" data-act="sim-csv">Export results ↗</button></div><div class="callout" id="sim-explain" style="margin-top:20px">${esc(r.text)}${r.equation?`<div style="white-space:pre-line;margin-top:10px;font-weight:600">${esc(r.equation)}</div>`:''}</div></div></section><section class="panel glass" style="margin-top:18px"><div class="panel-head"><h2>What the model tells us</h2><span class="muted" style="font-size:10px">Live calculation</span></div><div class="panel-body" id="sim-results"></div></section><section class="panel glass" style="margin-top:18px"><div class="panel-head"><h2>Your trials</h2><button class="btn small" data-act="trial-notebook">Send to notebook ↗</button></div><div class="panel-body" id="trials"></div></section></div><aside><section class="panel glass"><div class="panel-head"><h2>The investigation</h2><span class="badge">${esc(p.ref)}</span></div><div class="panel-body"><ol class="step-list">${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="reaction-box">${esc(p.equation)}</div><p class="hint" style="margin-top:16px">Virtual investigation and revision method. Real practicals require a school laboratory and teacher supervision.</p></div></section><section class="panel glass" style="margin-top:18px"><div class="panel-head"><h2>A fair comparison</h2></div><div class="panel-body"><dl class="variables">${p.variables.map((v,i)=>`<div><dt>${['INDEPENDENT','DEPENDENT','CONTROL'][i]}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><details style="margin-top:20px;font-size:11px"><summary>Think it through</summary><p style="margin:12px 0">${esc(p.question)}</p><button class="btn small" data-act="reveal-practical">Reveal answer</button><p id="practical-answer" hidden style="margin-top:12px">${esc(p.answer)}</p></details><button class="btn small" style="width:100%;margin-top:20px" data-act="mark-practical">${state.practised.includes(p.id)?'✓ Explored':'Mark as explored'}</button></div></section></aside></div>`;
 updateSimResults(r);renderTrials();$$('[data-param]').forEach(el=>el.oninput=e=>{const key=e.target.dataset.param;params[key]=Number(e.target.value);const c=controls[p.id].find(c=>c.key===key);if(!c.options)e.target.previousElementSibling.querySelector('output').textContent=fmt(params[key],3)+' '+c.unit;const r=simulate(p.id,params);$('#sim-stage').innerHTML=stageHTML(p.id,params,r);$('#sim-explain').innerHTML=esc(r.text)+(r.equation?`<div style="white-space:pre-line;margin-top:10px;font-weight:600">${esc(r.equation)}</div>`:'');updateSimResults(r);save();});
}
function updateSimResults(r){$('#sim-results').innerHTML=`<div class="table-scroll"><table class="data-table"><tbody>${r.metrics.map(([k,v])=>`<tr><th scope="row">${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div>${graphHTML(r,compare)}${compare?'<p class="hint">Blue: current model · green dashed: pinned comparison</p>':''}`;}
function renderTrials(){const trials=state.trials[practicalID]||[];$('#trials').innerHTML=trials.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Trial</th><th>Recorded</th><th>Result</th></tr></thead><tbody>${trials.map((t,i)=>`<tr><td>${i+1}</td><td>${esc(date(t.date))}</td><td>${t.metrics.slice(0,2).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Change an input, then record a trial. Your results stay on this device.</p>';}
function renderLearn(){const l=lessons.find(l=>l.id===lessonID)||lessons[0];main.innerHTML=heading('Understand a little more.','A course-wide revision library, with retrieval practice that remembers your progress.',`<div class="row"><button class="btn" data-act="flashcards">Flashcards</button><button class="btn primary" data-act="start-quiz">Quick practice ↗</button></div>`,'LEARN. CONNECT. REMEMBER.')+`<div class="stats"><div class="metric"><label>TOPICS REVIEWED</label><strong>${state.mastered.length}<small> / ${lessons.length}</small></strong></div><div class="metric"><label>PRACTICALS EXPLORED</label><strong>${state.practised.length}<small> / 18</small></strong></div><div class="metric"><label>PRACTICE ACCURACY</label><strong>${state.score.total?Math.round(state.score.correct/state.score.total*100):0}<small>% · ${state.score.total} answered</small></strong></div></div><div class="lesson-layout"><section class="panel glass"><div class="panel-head"><h2>Your learning map</h2></div><div class="lesson-list">${lessons.map(t=>`<button class="lesson-link ${l.id===t.id?'active':''}" data-act="lesson" data-id="${t.id}"><b>${state.mastered.includes(t.id)?'✓ ':''}${esc(t.title)}</b><small>${esc(t.strand)} · ${esc(t.ref)}</small></button>`).join('')}</div></section><article class="panel glass"><div class="panel-body reading"><span class="badge">${esc(l.strand)} · ${esc(l.ref)}</span><h2>${esc(l.title)}</h2><p>${esc(l.text)}</p><div class="callout"><b>Keep this distinction clear.</b><br>${esc(l.tip)}</div><details><summary>Check your understanding</summary><p>${esc(l.question)}</p><button class="btn small" data-act="reveal-lesson">Reveal answer</button><p id="lesson-answer" hidden>${esc(l.answer)}</p></details><div class="row wrap" style="margin-top:30px"><button class="btn primary" data-act="mastered">${state.mastered.includes(l.id)?'✓ Reviewed · mark unread':'Mark as reviewed'}</button><button class="btn" data-act="next-lesson">Next topic →</button></div><p class="hint" style="margin-top:30px">Original study notes, organised around Edexcel 4CH1. Topic summaries support revision; use the <a href="${specURL}" target="_blank" rel="noopener">official specification</a> for the full learning statements.</p></div></article></div>`;}
function shuffle(a){return [...a].sort(()=>Math.random()-.5);}
function startQuiz(mode){quiz={mode,items:shuffle(lessons).slice(0,mode==='flash'?lessons.length:10),correct:0,answers:[]};quizIndex=0;quizRevealed=false;setOptions();render();}
function setOptions(){if(!quiz||quizIndex>=quiz.items.length)return;const l=quiz.items[quizIndex];quizOptions=shuffle([l.answer,...shuffle(lessons.filter(x=>x.id!==l.id)).slice(0,3).map(x=>x.answer)]);}
function renderQuiz(){if(quizIndex>=quiz.items.length){main.innerHTML=heading('A little progress, every time.','Your practice session is complete. Every answer is a useful next step.')+`<section class="panel glass"><div class="panel-body reading"><h2>${quiz.mode==='flash'?'Deck complete.':quiz.correct+' / '+quiz.items.length+' correct.'}</h2><p>${quiz.mode==='flash'?'You worked through the topic deck.':'Revisit any missed concepts below.'}</p>${quiz.answers.filter(a=>!a.correct).map(a=>`<div class="callout" style="margin:10px 0"><b>${esc(a.lesson.question)}</b><br>${esc(a.lesson.answer)}</div>`).join('')}<button class="btn primary" data-act="end-quiz">Back to learning</button></div></section>`;return;}
 const l=quiz.items[quizIndex];main.innerHTML=heading(quiz.mode==='flash'?'A thought to turn over.':'Put your understanding to work.',`${quiz.mode==='flash'?'Flashcard':'Question'} ${quizIndex+1} of ${quiz.items.length}`,`<button class="btn subtle" data-act="end-quiz">Finish session</button>`,'RETRIEVAL PRACTICE')+`<section class="panel glass"><div class="panel-body reading" style="margin:auto;padding:35px;max-width:850px"><div class="progress-track"><i style="width:${quizIndex/quiz.items.length*100}%"></i></div><p class="muted" style="font-size:11px">${esc(l.strand)} · ${esc(l.title)}</p><h2>${esc(l.question)}</h2>${quiz.mode==='flash'?`<div class="callout" ${quizRevealed?'':'hidden'}>${esc(l.answer)}</div><div class="row" style="margin-top:25px">${quizRevealed?'<button class="btn primary" data-act="next-question">Next card →</button>':'<button class="btn primary" data-act="flip-card">Turn card ↻</button>'}</div>`:`<div class="quiz-options">${quizOptions.map((o,i)=>`<button class="quiz-option ${quizRevealed&&o===l.answer?'correct':quizRevealed&&quiz.answers.at(-1)?.choice===i?'wrong':''}" data-act="quiz-answer" data-id="${i}" ${quizRevealed?'disabled':''}>${esc(o)}</button>`).join('')}</div>${quizRevealed?`<div class="callout">${esc(l.tip)}</div><button class="btn primary" style="margin-top:20px" data-act="next-question">Next question →</button>`:''}`}</div></section>`;}
function elementType(e){if(e.n>=57&&e.n<=71)return 'Lanthanides';if(e.n>=89&&e.n<=103)return 'Actinides';if(e.g===18)return 'Noble gases';if(e.g===17)return 'Halogens';if(e.g===1&&e.n!==1)return 'Alkali metals';if(e.g===2)return 'Alkaline earth';if([5,14,32,33,51,52].includes(e.n))return 'Metalloids';if([1,6,7,8,15,16,34].includes(e.n))return 'Non-metals';if(e.g>=3&&e.g<=12)return 'Transition metals';return 'Other metals';}
const elementColors={'Alkali metals':'#d6a26d','Alkaline earth':'#cab77a','Transition metals':'#8ea7d3','Other metals':'#9bbac7','Metalloids':'#85b5a4','Non-metals':'#70b8be','Halogens':'#b695be','Noble gases':'#a69acb','Lanthanides':'#b6a5cb','Actinides':'#c8a2b7'};
function renderPeriodic(){main.innerHTML=heading('Meet the building blocks.','All 118 elements. One connected story.',`<span class="pill">Tap an element to explore</span>`,'THE PERIODIC TABLE')+`<section class="panel glass"><div class="panel-body"><div class="catalog-tools"><input id="element-search" class="search" aria-label="Find an element" value="${esc(elementQuery)}" placeholder="Find by name, symbol or number…"><select id="element-filter" aria-label="Filter element families"><option>All</option>${Object.keys(elementColors).map(t=>`<option ${elementFilter===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="periodic-scroll"><div class="periodic" id="periodic-grid"></div></div><div class="row wrap" style="margin-top:22px">${Object.entries(elementColors).map(([k,c])=>`<span class="pill" style="font-size:9px"><span class="dot" style="--chem:${c};margin:0"></span>${k}</span>`).join('')}</div><p class="hint" style="margin-top:20px">Decimal values are rounded relative atomic masses. For elements without a standard atomic weight, a representative isotope mass number is shown. In exam calculations, use the relative atomic masses supplied in the question.</p></div></section>`;renderElements();$('#element-search').oninput=e=>{elementQuery=e.target.value;renderElements();};$('#element-filter').onchange=e=>{elementFilter=e.target.value;renderElements();};}
function renderElements(){$('#periodic-grid').innerHTML=elements.map(e=>{let row=e.p,col=e.g;if(e.n>=57&&e.n<=71){row=9;col=e.n-54;}if(e.n>=89&&e.n<=103){row=10;col=e.n-86;}const q=elementQuery.toLowerCase(),dim=(elementFilter!=='All'&&elementType(e)!==elementFilter)||!(`${e.n} ${e.s} ${e.nm}`.toLowerCase().includes(q));return `<button class="element ${dim?'dim':''}" style="grid-column:${col};grid-row:${row};--el:${elementColors[elementType(e)]}" data-act="element" data-id="${e.n}" aria-label="${e.n} ${esc(e.nm)}"><span>${e.n}</span><b>${e.s}</b><small>${esc(e.nm)}</small></button>`;}).join('');}
function renderTools(){main.innerHTML=heading('Let the numbers make sense.','Show your working, check your units, and connect the calculation to the chemistry.','','A SMALL TOOLKIT FOR BIG QUESTIONS')+`<div class="tool-grid"><section class="panel glass"><div class="panel-head"><h2>Equation balancer</h2><span class="badge">Conserves atoms</span></div><div class="panel-body"><form id="balance-form" class="tool-form"><div class="field"><label for="equation">Reactants → products</label><input id="equation" required value="Fe + O2 -> Fe2O3" placeholder="H2 + O2 -> H2O"></div><button class="btn primary">Balance equation</button></form><p class="tools-help">Use neutral formulae, + and → or ->. Round brackets and hydrates with · are supported. Ionic charge balancing is outside this tool.</p><div id="balance-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Formula mass & composition</h2></div><div class="panel-body"><form id="mass-form" class="tool-form"><div class="field"><label for="formula">Chemical formula</label><input id="formula" value="CuSO4·5H2O" required></div><button class="btn primary">Calculate molar mass</button></form><div id="mass-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Quantities calculator</h2></div><div class="panel-body"><form id="quantity-form" class="tool-form"><div class="field"><label for="quantity-mode">Calculation</label><select id="quantity-mode"><option value="moles">Moles: mass ÷ molar mass</option><option value="concentration">Concentration: moles ÷ volume (dm³)</option><option value="gas">Gas volume at RTP (dm³)</option><option value="yield">Percentage yield</option><option value="energy">Q = mass × 4.18 × ΔT</option><option value="enthalpy">ΔH = −Q ÷ n (kJ/mol)</option><option value="rf">Chromatography Rf</option><option value="empirical">Empirical ratio from two masses</option></select></div><div class="field"><label id="qa-label" for="qa">Mass / g</label><input id="qa" type="number" value="4.8" step="any" required></div><div class="field" id="qb-wrap"><label id="qb-label" for="qb">Molar mass / g mol⁻¹</label><input id="qb" type="number" value="24" step="any" required></div><div id="empirical-extra" hidden><div class="row">${field('arA','Ar of first element',24,'number','step="any"')}${field('arB','Ar of second element',16,'number','step="any"')}</div></div><button class="btn primary">Show working</button></form><div id="quantity-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Bond-energy calculation</h2><span class="badge">3.7C</span></div><div class="panel-body"><p class="hint" style="margin-bottom:18px">Enter total energy for all bonds broken and all bonds formed, using the balanced equation. Example: H₂ + Cl₂ → 2HCl, 436 + 243 broken and 2 × 431 formed.</p><form id="bond-form" class="tool-form">${field('broken','Total bonds broken / kJ mol⁻¹',679,'number','step="any" min="0" required')}${field('formed','Total bonds formed / kJ mol⁻¹',862,'number','step="any" min="0" required')}<button class="btn primary">Calculate ΔH</button></form><div id="bond-result" aria-live="polite"></div></div></section>${extraToolsHTML()}</div>`;
 mountExtraTools(main);
 const result=(target,fn)=>{try{$(target).innerHTML=`<div class="result">${fn()}</div>`;}catch(e){$(target).innerHTML=`<div class="result error">${esc(e.message)}</div>`;}};
 $('#balance-form').onsubmit=e=>{e.preventDefault();result('#balance-result',()=>{const parts=$('#equation').value.trim().split(/->|→|=/);if(parts.length!==2)throw Error('Use one arrow between reactants and products.');const sides=parts.map(s=>s.split('+').map(s=>s.trim().replace(/^\d+(?=[A-Z(])/,'')).filter(Boolean));if(sides.some(s=>!s.length)||sides.flat().length>12)throw Error('Enter 1–12 valid species.');sides.flat().forEach(f=>molarMass(f,elements));const b=balance(...sides);return `<b>${chemText(b.text)}</b><br><span class="hint">Coefficients: ${b.coefficients.join(' : ')}. Each element is conserved.</span>`;});};
 $('#mass-form').onsubmit=e=>{e.preventDefault();result('#mass-result',()=>{const formula=$('#formula').value.trim(),mass=molarMass(formula,elements),atoms=parseFormula(formula);return `${chemText(formula)}<br><b>${fmt(mass,3)} g/mol</b><br>${Object.entries(atoms).map(([s,n])=>s+': '+fmt(n*Number(elements.find(e=>e.s===s).m.replace(/[()]/g,''))/mass*100)+'% by mass').join(' · ')}`;});};
 const labels={moles:['Mass / g','Molar mass / g mol⁻¹'],concentration:['Amount / mol','Solution volume / cm³'],gas:['Amount of gas / mol',''],yield:['Actual yield / g','Theoretical yield / g'],energy:['Mass of water / g','Temperature change / °C'],enthalpy:['Heat gained by surroundings Q / J','Amount reacted / mol'],rf:['Spot distance from baseline / cm','Solvent-front distance / cm'],empirical:['First element mass / g','Second element mass / g']};
 $('#quantity-mode').onchange=e=>{const k=e.target.value;$('#qa-label').textContent=labels[k][0];$('#qb-label').textContent=labels[k][1];$('#qb-wrap').hidden=!labels[k][1];$('#empirical-extra').hidden=k!=='empirical';$('#quantity-result').innerHTML='';};
 $('#quantity-form').onsubmit=e=>{e.preventDefault();result('#quantity-result',()=>{const k=$('#quantity-mode').value,a=Number($('#qa').value),b=Number($('#qb').value);if(!Number.isFinite(a)||!Number.isFinite(b)||(!['energy','enthalpy'].includes(k)&&a<0)||k!=='gas'&&b===0)throw Error('Use finite, physically valid values; the divisor must be positive.');if(!['gas','energy'].includes(k)&&b<=0)throw Error('The divisor must be positive.');
  if(k==='moles')return `n = ${a} ÷ ${b} = <b>${fmt(a/b,6)} mol</b>`;if(k==='concentration')return `c = ${a} ÷ (${b} ÷ 1000) = <b>${fmt(a/(b/1000),6)} mol/dm³</b>`;if(k==='gas')return `V = ${a} × 24 = <b>${fmt(a*24,6)} dm³ at RTP</b>`;if(k==='yield')return `yield = ${a} ÷ ${b} × 100 = <b>${fmt(a/b*100)}%</b>${a>b?'<p class="hint">Above 100% suggests a wet/impure product or measurement error.</p>':''}`;if(k==='energy'){if(a<=0)throw Error('Mass must be positive.');return `Q = ${a} × 4.18 × ${b} = <b>${fmt(a*4.18*b)} J</b>`;}if(k==='enthalpy')return `ΔH = −${a} ÷ ${b} ÷ 1000 = <b>${fmt(-a/b/1000,4)} kJ/mol</b>`;if(k==='rf'){if(a>b)throw Error('A spot cannot travel beyond the solvent front in this model.');return `Rf = ${a} ÷ ${b} = <b>${fmt(a/b,4)}</b> (no unit)`;}if(k==='empirical'){const arA=Number($('#field-arA').value),arB=Number($('#field-arB').value);if(arA<=0||arB<=0||a<=0||b<=0)throw Error('Masses and relative atomic masses must be positive.');const n1=a/arA,n2=b/arB,min=Math.min(n1,n2);return `Moles: ${fmt(n1,5)} and ${fmt(n2,5)}<br>Ratio: <b>${fmt(n1/min,3)} : ${fmt(n2/min,3)}</b><br>Multiply fractional ratios to get the simplest whole numbers; use your experimental uncertainty.`;}});};
 $('#bond-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);result('#bond-result',()=>{const b=Number(f.get('broken')),m=Number(f.get('formed'));if(!Number.isFinite(b)||!Number.isFinite(m)||b<0||m<0)throw Error('Enter positive bond-energy totals.');return `ΔH = ${b} − ${m} = <b>${fmt(b-m)} kJ/mol</b><br>${b<m?'Exothermic':b>m?'Endothermic':'No net enthalpy change in this estimate'}`;});};
}
function addNote(title,body){const n={id:'note-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),title,body,date:new Date().toISOString()};state.notes.unshift(n);noteID=n.id;if(state.notes.length>100)state.notes.pop();save();toast('Added to your lab notebook.');}
function renderNotebook(){const n=state.notes.find(n=>n.id===noteID)||state.notes[0];noteID=n?.id;main.innerHTML=heading('Keep the thought.','Your observations, questions and “I wonder…” moments, saved together.',`<div class="row"><button class="btn" data-act="export-notes">Export notes ↗</button><button class="btn primary" data-act="new-note">＋ New entry</button></div>`,'THE LAB NOTEBOOK')+`<div class="notebook-layout"><section class="panel glass"><div class="panel-head"><h2>Entries</h2><span class="badge">${state.notes.length}</span></div><div class="panel-body" style="padding:10px">${state.notes.map(t=>`<button class="notebook-entry ${t.id===noteID?'active':''}" data-act="note" data-id="${t.id}"><h3>${esc(t.title||'Untitled entry')}</h3><small>${date(t.date)}</small></button>`).join('')||'<div class="empty">A clean page for a curious mind.</div>'}</div></section><section class="panel glass"><div class="panel-head"><h2>${n?'Your observation':'Start a new entry'}</h2>${n?'<button class="btn small danger" data-act="delete-note">Delete entry</button>':''}</div><div class="panel-body notebook-editor">${n?`<label class="mini-label" for="note-title">ENTRY TITLE</label><input id="note-title" value="${esc(n.title)}" maxlength="200"><div class="hint">${date(n.date)} · autosaved locally</div><label class="mini-label" style="display:block" for="note-body">METHOD, RESULTS & REFLECTIONS</label><textarea id="note-body" maxlength="100000" placeholder="What did you change? What did you observe? What does it tell you?">${esc(n.body)}</textarea><div class="row"><button class="btn small" data-act="export-entry">Export this entry</button><button class="btn small" data-act="print">Print</button></div>`:'<div class="empty">Record a practical, save a bench observation, or create a new note.</div>'}</div></section></div>`;if(n){$('#note-title').oninput=e=>{n.title=e.target.value;save();};$('#note-body').oninput=e=>{n.body=e.target.value;save();};}}
function benchReport(){const v=selected(),a=appearance(v);return `${v.name}\n${fmt(v.volume)} mL · ${fmt(v.temp)}°C\nModel pH: ${a.ph===null?'outside model':fmt(a.ph)}\n\nContents:\n${v.contents.map(s=>`${s.chem.name} (${s.chem.formula}, ${s.chem.state}): ${s.n.toExponential(4)} mol`).join('\n')}\n\nObservation log:\n${v.events.map(e=>`${date(e.time)} — ${e.text}${e.equation?'\n'+e.equation:''}`).join('\n')}\n\nInterpretation:\n\nEvaluation / improvements:\n`;}
function exportTrials(){const r=simulate(practicalID,simParams()),trials=state.trials[practicalID]||[],csvCell=v=>'"'+String(v).replace(/"/g,'""')+'"',rows=[['Trial','Date','Quantity','Value']];trials.forEach((t,i)=>t.metrics.forEach(([k,v])=>rows.push([i+1,t.date,k,v])));if(!trials.length)r.metrics.forEach(([k,v])=>rows.push(['Live model',new Date().toISOString(),k,v]));if(r.points){rows.push([],['Current curve',r.xLabel,r.yLabel]);r.points.forEach(([x,y])=>rows.push(['',x,y]));}download('chemlab-'+practicalID+'.csv',rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv');}
const actions={
 nav:id=>{page=id;practicalID=null;quiz=null;location.hash=id;render();},close:()=>closeInlinePanel(),dose:doseDialog,'select-vessel':id=>{state.selected=Number(id);state.sandbox.selectedItem=null;save();render();},'shelf-filter':id=>{shelfFilter=id;render();},
 'rename-vessel':()=>{const v=selected();formModal('Name this vessel',field('name','Name',v.name,'text','maxlength="80" required'),f=>{checkpoint();v.name=String(f.get('name')).trim()||v.name;});},
 'empty-vessel':()=>{const v=selected();checkpoint();const n=makeVessel(v.id,v.shape);n.name=v.name;n.x=v.x;n.y=v.y;state.vessels[state.vessels.indexOf(v)]=n;save();render();},
 'remove-vessel':()=>{const v=selected();mutate(()=>{detachLabObject(state,'vessel',v.id,true);state.vessels=state.vessels.filter(w=>w.id!==v.id);state.selected=state.vessels[0]?.id;});},
 undo:()=>{if(undo.length){const previous=JSON.parse(undo.pop());state.vessels=previous.vessels;state.sandbox=previous.sandbox||newSandbox();state.nextVessel=Math.max(0,...state.vessels.map(v=>v.id))+1;state.selected=state.vessels.some(v=>v.id===state.selected)?state.selected:state.vessels[0]?.id;save();render();toast('Restored the previous bench state.');}},
 heat:()=>{const v=selected();formModal('Controlled heating',`<p>Choose a target temperature. Liquids are held at 100°C in this simplified aqueous model; high-temperature organic behaviour is outside the model.</p>${field('temp','Temperature / °C',Math.min(v.volume?100:400,v.temp+40),'number','min="20" max="800" step="any" required')}<p class="hint">Heating can trigger supported carbonate decomposition (simplified 250°C threshold) or the ammonium test. It does not assert every thermal reaction or simulate a rate.</p>`,f=>{const t=Number(f.get('temp'));if(t>100&&v.volume>0)throw Error('Keep liquid samples at or below 100°C.');if(t<20||t>800)throw Error('Choose 20–800°C.');checkpoint();v.temp=t;v.heated=t>20;v.events.push({time:new Date().toISOString(),type:'heating',text:`Set temperature to ${t}°C (controlled-temperature model).`});resolve(v);});},
 transfer:()=>transferDialog(false),filter:()=>transferDialog(true),
 evaporate:()=>{const v=selected();formModal('Remove water by evaporation',`<p>Choose a water volume to remove. The model leaves non-volatile salts when an aqueous sample reaches dryness. For hydrated crystals, use Crystallise and cooling instead.</p>${field('ml','Water to remove / mL',v.volume/2,'number','min="0.001" step="any" required')}`,f=>{const n=Number(f.get('ml'));checkpoint();try{evaporate(v,n);}catch(e){undo.pop();throw e;}});},
 crystallise:()=>{const v=selected();formModal('Crystallise a dissolved salt',`<p>Partly remove solvent, then cool the solution to recover crystals. This bench shortcut uses a chosen recovery fraction; it does not predict solubility.</p>${field('recovery','Salt recovery / %',70,'number','min="1" max="90" step="1" required')}<p class="hint">Only dissolved salts are recovered. Copper sulfate is shown as the hydrated pentahydrate. Remaining solute stays in the mother liquor. Use the solubility workspace for saturation calculations.</p>`,f=>{const salts=v.contents.filter(s=>s.chem.category==='salt'&&s.chem.state==='aqueous');if(!salts.length||v.volume<=0)throw Error('Add a dissolved salt first.');const fraction=Number(f.get('recovery'))/100;if(fraction<=0||fraction>.9)throw Error('Choose a recovery between 1 and 90%.');checkpoint();salts.forEach(s=>{const n=s.n*fraction;s.n-=n;const hydrate=s.chem.formula==='CuSO4';const c={...s.chem,id:'product:'+s.chem.formula+(hydrate?'5H2O':''),name:s.chem.name+(hydrate?' pentahydrate crystals':' crystals'),formula:s.chem.formula+(hydrate?'·5H2O':''),state:'solid'};const existing=v.contents.find(s=>s.chem.id===c.id&&s.chem.state==='solid');if(existing)existing.n+=n;else v.contents.push({chem:c,n});});v.events.push({time:new Date().toISOString(),type:'crystallisation',text:`Recovered ${fmt(fraction*100)}% of dissolved salts as crystals (specified recovery, not a solubility prediction). Separate crystals by filtration.`});});},
 'gas-test':()=>{const v=selected();modal('A gas leaves a clue',`<p>Products collected virtually at room conditions:</p>${Object.entries(v.gas).map(([g,n])=>`<div class="callout" style="margin-top:12px"><b>${chemText(g)} · ${fmt(n*24000)} mL</b><br>${esc(gasTests[g]?.[0]||'No syllabus test provided')}<br>${esc(gasTests[g]?.[1]||'Use a suitable analytical method.')}</div>`).join('')||'<div class="empty">No gas has formed in this vessel yet.</div>'}`);},
 history:()=>{const v=selected();modal('The story of this vessel',`<div class="timeline">${[...v.events].reverse().map(e=>`<p><small>${date(e.time)}</small>${esc(e.text)}${e.equation?'<br>'+chemText(e.equation):''}</p>`).join('')||'<p>No events recorded.</p>'}</div>`);},
 demo:()=>mutate(()=>{if(state.vessels.length>=24)throw Error('Remove a vessel before loading the example.');const v=makeVessel(state.nextVessel++);state.vessels.push(v);state.selected=v.id;dose(v,chemicals.find(c=>c.id==='cuso4'),50,.1,elements);dose(v,chemicals.find(c=>c.id==='fe'),.28,.1,elements);toast('Iron displaces copper: look for the copper deposit.');}),
 'record-bench':()=>addNote('Bench observation · '+selected().name,benchReport()),
 export:()=>download('chemlab-workspace.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json'),
 import:()=>$('#import-file').click(),
 theme:()=>{state.theme=state.theme==='light'?'dark':'light';save();applySettings();},
 settings:()=>modal('Your workspace',`<p>Your experiments, notes and progress are stored in this browser on this device. Export a workspace backup to move them or keep a separate copy.</p><div class="row wrap"><button class="btn" data-act="export">Export workspace</button><button class="btn" data-act="import">Import workspace</button><a class="btn" href="Chemlab.html" download="Chemlab.html">Download offline app</a></div><label class="check"><input id="motion" type="checkbox" ${state.motion?'checked':''}>Reduce animation</label><p class="hint">The system’s reduced-motion preference is also respected.</p>`),
 practical:id=>{practicalID=id;page='practicals';compare=null;location.hash='practicals/'+id;render();},'all-practicals':()=>{practicalID=null;compare=null;location.hash='practicals';render();},'catalog-filter':id=>{catalogFilter=id;render();},
 'record-trial':()=>{const p=practicals.find(p=>p.id===practicalID),r=simulate(p.id,simParams());const t=state.trials[p.id]||(state.trials[p.id]=[]);t.push({date:new Date().toISOString(),metrics:r.metrics,params:{...simParams()}});if(t.length>50)t.shift();if(!state.practised.includes(p.id))state.practised.push(p.id);save();renderTrials();toast('Trial '+t.length+' recorded.');},
 'reset-sim':()=>{state.params[practicalID]=defaults(practicalID);save();render();},compare:()=>{compare=compare?null:simulate(practicalID,simParams());render();},'sim-csv':exportTrials,
 'trial-notebook':()=>{const p=practicals.find(p=>p.id===practicalID),t=state.trials[p.id]||[];if(!t.length){toast('Record a trial first.');return;}addNote(p.title+' · practical report',`${p.title}\nSpecification: ${p.ref}\n\nMethod:\n${p.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\nResults:\n${t.map((t,i)=>`Trial ${i+1} (${date(t.date)})\n${t.params?Object.entries(t.params).map(([k,v])=>`${k}: ${v}`).join('; ')+'\n':''}${t.metrics.map(([k,v])=>`${k}: ${v}`).join('\n')}`).join('\n\n')}\n\nModel assumptions:\n${simulate(p.id,simParams()).text}\n\nConclusion:\n\nEvaluation:\n`);},
 'reveal-practical':()=>{$('#practical-answer').hidden=false;},'mark-practical':()=>{if(!state.practised.includes(practicalID))state.practised.push(practicalID);save();render();},
 lesson:id=>{lessonID=id;render();},'reveal-lesson':()=>{$('#lesson-answer').hidden=false;},mastered:()=>{state.mastered=state.mastered.includes(lessonID)?state.mastered.filter(id=>id!==lessonID):[...state.mastered,lessonID];save();render();},'next-lesson':()=>{lessonID=lessons[(lessons.findIndex(l=>l.id===lessonID)+1)%lessons.length].id;render();},
 'start-quiz':()=>startQuiz('quiz'),flashcards:()=>startQuiz('flash'),'end-quiz':()=>{quiz=null;render();},'flip-card':()=>{quizRevealed=true;render();},
 'quiz-answer':id=>{if(quizRevealed)return;const l=quiz.items[quizIndex],i=Number(id),correct=quizOptions[i]===l.answer;quizRevealed=true;quiz.answers.push({lesson:l,choice:i,correct});quiz.correct+=Number(correct);state.score.correct+=Number(correct);state.score.total++;save();render();},
 'next-question':()=>{quizIndex++;quizRevealed=false;setOptions();render();},
 element:id=>{const e=elements.find(e=>e.n===Number(id)),config=e.n<=20?(e.n<=2?[e.n]:e.n<=10?[2,e.n-2]:e.n<=18?[2,8,e.n-10]:[2,8,8,e.n-18]).join(', '):'First-20 shell model not applied';modal(e.nm,`<div class="row" style="align-items:start"><div style="font-size:65px;line-height:1;padding:10px 20px;background:${elementColors[elementType(e)]}30;border-radius:20px">${e.s}</div><div><span class="badge">${elementType(e)}</span><h2 style="margin-top:12px">${e.nm}</h2><p>Atomic number ${e.n} · period ${e.p}</p></div></div><div class="metric-pair" style="margin-top:20px"><div class="metric"><label>RELATIVE ATOMIC MASS / ISOTOPE</label><strong>${e.m}</strong></div><div class="metric"><label>PROTONS</label><strong>${e.n}</strong></div></div><p><b>Electron shells:</b> ${config}</p><p class="hint">A neutral atom has ${e.n} electrons. Neutron count requires a specific isotope mass number. Relative atomic mass is not generally a mass number.</p>`);},
 'new-note':()=>{addNote('A new observation','Question / aim:\n\nPrediction:\n\nMethod:\n\nResults:\n\nConclusion:\n\nEvaluation:\n');render();},note:id=>{noteID=id;render();},
 'delete-note':()=>formModal('Delete this notebook entry',`<p>Remove “${esc(state.notes.find(n=>n.id===noteID)?.title)}” from this device? Export it first if you need a copy.</p>`,()=>{state.notes=state.notes.filter(n=>n.id!==noteID);noteID=state.notes[0]?.id;}),
 'export-notes':()=>download('chemlab-notebook.txt',state.notes.map(n=>n.title+'\n'+date(n.date)+'\n\n'+n.body).join('\n\n'+'─'.repeat(50)+'\n\n')),
 'export-entry':()=>{const n=state.notes.find(n=>n.id===noteID);download('chemlab-entry.txt',n.title+'\n'+n.body);},print:()=>window.print(),
 about:()=>modal('Thoughtful chemistry. Clear boundaries.',`<p>Chemlab 2 is an independent study companion for Edexcel International GCSE Chemistry (linear 4CH1). Its 18 workspaces include the 12 named practical investigations, plus revision tools and original topic notes. It is not endorsed by Pearson or Apple.</p><p>The bench supports measured neutralisation, selected acid–metal, acid–oxide and carbonate reactions, selected precipitation, Group 1/calcium reactions with water, displacement, peroxide/MnO₂ catalysis, ammonium tests and carbonate decomposition. Unknown combinations are retained without a prediction. Organic reactions, electrolysis, rates and other specialised work use dedicated practical models.</p><p>Balanced equations conserve atoms. Stoichiometric calculations assume complete supported reactions. pH is an ideal 25°C charge-balance model for strong acids/alkalis, ethanoic acid, ammonia and selected salts; metal-ion hydrolysis, activities and many polyprotic equilibria are outside it. Heated mixtures do not get a temperature-corrected pH. Gases use 24 dm³/mol at RTP.</p><p>Rate constants, visual motion, crystallisation recovery and the model-solute curve are illustrative. The bench is aqueous-focused: organic solvent miscibility, pressure, detailed kinetics, secondary redox and all possible combinations are outside its scope. Check specific assumptions in each practical.</p><p><a href="${specURL}" target="_blank" rel="noopener">Pearson 4CH1 specification · Issue 3, September 2024 ↗</a></p><p>Lab work stays in browser storage, separated by your Chemlab username. Back up with Export workspace. Account sessions use the hosted server; RevisionCore accounts remain separate.</p>`),
 help:()=>modal('Your lab, a little easier.',`<p><b>1. Set up.</b> Add a beaker, flask, test tube or evaporating dish. Tap it to select it.</p><p><b>2. Measure.</b> Search the reagent library and tap or drag a reagent onto a vessel. Enter volume and concentration, or mass for solids.</p><p><b>3. Observe.</b> Supported chemistry resolves on addition. Read the quantities, equations and observations in Under the surface.</p><p><b>4. Explore.</b> Transfer, filter, heat, evaporate, crystallise or identify gas products. Undo restores the previous bench state.</p><p><b>5. Connect.</b> Open a practical for its own controls, graphs, methods and trials. Send results to your notebook or export CSV.</p><p><b>Keyboard:</b> use Tab and Enter for all controls. Press ? for help and Escape to dismiss a dialog. Back up your workspace from Settings.</p>`)
};
function transferDialog(filtering){const v=selected(),others=state.vessels.filter(w=>w.id!==v.id);if(!others.length){toast('Add a receiving vessel first.');return;}formModal(filtering?'Separate solid from solution':'Pour a measured fraction',`<p>${filtering?'Filtrate collects in the receiving vessel; insoluble solids remain as residue in the source.':'This transfers a homogeneous fraction of the stirred mixture, including suspended solids.'}</p><div class="field"><label for="target">Receiving vessel</label><select id="target" name="target">${others.map(w=>`<option value="${w.id}">${esc(w.name)} · ${fmt(w.capacity-w.volume)} mL free</option>`).join('')}</select></div>${filtering?'':field('percent','Fraction of source mixture / %',50,'number','min="0.1" max="100" step="any" required')}`,f=>{const dest=state.vessels.find(w=>w.id===Number(f.get('target')));checkpoint();try{filtering?filterVessel(v,dest):transfer(v,dest,Number(f.get('percent')));}catch(e){undo.pop();throw e;}});}
function sandboxSpawn(token,position){
 const [type,kind]=token.split(':');const viewport=$('#sandbox-viewport');if(!position){const w=viewport?.clientWidth||600,h=viewport?.clientHeight||650;position={x:(w/2-state.sandbox.panX)/state.sandbox.zoom-70,y:(h*.48-state.sandbox.panY)/state.sandbox.zoom-100};}
 if(type==='vessel'){
  if(!['beaker','flask','tube','dish'].includes(kind))return;if(state.vessels.length>=24)throw Error('This workspace holds up to 24 vessels.');checkpoint();
  const v=makeVessel(state.nextVessel++,kind);v.x=Math.max(0,Math.min(1440,position?.x??(260+state.vessels.length%5*190)));v.y=Math.max(0,Math.min(760,position?.y??220));state.vessels.push(v);state.selected=v.id;
 }else if(type==='apparatus'&&apparatusKinds[kind]){
  if(state.sandbox.items.length>=30)throw Error('This workspace holds up to 30 apparatus items.');checkpoint();state.sandbox.items.push({id:state.sandbox.nextId++,kind,x:Math.max(0,Math.min(1440,position?.x??600)),y:Math.max(0,Math.min(760,position?.y??250)),on:false,targetId:null,sourceId:null,remainingMl:0,deliveredMl:0,concentration:.1,elapsed:0});
 }else return;
 normaliseSandbox(state);if(type==='apparatus')state.sandbox.selectedItem=state.sandbox.items.at(-1).id;else state.sandbox.selectedItem=null;const created=type==='vessel'?state.vessels.at(-1):state.sandbox.items.at(-1),snap=findLabSnap(state,type==='vessel'?'vessel':'apparatus',created.id,90);if(snap?.kind==='attach')commitLabSnap(state,type==='vessel'?'vessel':'apparatus',created.id,snap);save();closeInlinePanel();render();
}
function sandboxDrop(id,equipmentId,position){
 if(id.startsWith('vessel:')||id.startsWith('apparatus:')){sandboxSpawn(id,position);return;}
 if(!chemicals.some(c=>c.id===id))return;
 if(equipmentId){const item=state.sandbox.items.find(i=>i.id===equipmentId);try{directBuretteFill(item,id);}catch(error){toast(error.message);}return;}
 if(position){sandboxSpawn('apparatus:bottle',position);const item=state.sandbox.items.at(-1);item.loadedId=id;state.sandbox.selectedItem=item.id;save();render();}
}
function apparatusItem(id){return state.sandbox.items.find(i=>i.id===Number(id));}
function apparatusMenu(id){const item=apparatusItem(id);if(!item)return;state.sandbox.selectedItem=item.id;save();render();}
function apparatusConnect(id){
 const item=apparatusItem(id);if(!item)return;if(!state.vessels.length){toast('Add a vessel first.');return;}
 const options=selectedId=>state.vessels.map(v=>`<option value="${v.id}" ${v.id===selectedId?'selected':''}>${esc(v.name)}</option>`).join('');
 formModal('Connect '+apparatusKinds[item.kind].name,`${item.kind==='funnel'?`<div class="field"><label for="source">Source mixture</label><select id="source" name="source">${options(item.sourceId)}</select></div>`:''}<div class="field"><label for="receiver">${item.kind==='funnel'?'Filtrate receiver':'Connected vessel'}</label><select id="receiver" name="target">${options(item.targetId||selected()?.id)}</select></div>`,form=>{const target=Number(form.get('target')),source=Number(form.get('source'));if(item.kind==='funnel'&&source===target)throw Error('Choose a different receiver from the source.');checkpoint();attachApparatusToVessel(item,state.vessels.find(v=>v.id===target));if(item.kind==='funnel')item.sourceId=source;});
}
function buretteLoad(id,reagentId){
 const item=apparatusItem(id);if(!item||item.kind!=='burette')return;
 const choices=chemicals.filter(c=>c.state==='aqueous'&&c.category!=='indicator'||c.id==='water');if(reagentId&&!choices.some(c=>c.id===reagentId)){toast('A burette holds aqueous solutions or water.');return;}
 formModal('Fill the burette',`<div class="field"><label for="burette-solution">Solution</label><select id="burette-solution" name="reagent">${choices.map(c=>`<option value="${c.id}" ${c.id===(reagentId||item.loadedId||'naoh')?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>${field('volume','Load volume / mL',50,'number','min="0.1" max="50" step="any" required')}${field('concentration','Concentration / mol dm⁻³',state.sandbox.dosing.concentration,'number','min="0.001" max="2" step="any" required')}`,form=>{const amount=Number(form.get('volume')),conc=Number(form.get('concentration'));if(!Number.isFinite(amount)||!Number.isFinite(conc)||amount<=0||amount>50||conc<=0||conc>2)throw Error('Choose 0–50 mL and a concentration up to 2 mol/dm³.');checkpoint();item.loadedId=form.get('reagent');item.remainingMl=amount;item.deliveredMl=0;item.concentration=conc;});
}
Object.assign(actions,{
 'shelf-tab':id=>{benchShelfTab=id;shelfQuery='';render();},
 'shelf-add':id=>sandboxSpawn(id),
 'add-vessel':()=>{benchShelfTab='apparatus';shelfQuery='';render();$('#reagents')?.scrollIntoView?.({block:'nearest'});},
 'apparatus-menu':apparatusMenu,'apparatus-connect':apparatusConnect,
 'apparatus-toggle':id=>{const item=apparatusItem(id);if(!item)return;checkpoint();item.on=!item.on;save();render();},
 'apparatus-remove':id=>{checkpoint();detachLabObject(state,'apparatus',Number(id),true);state.sandbox.items=state.sandbox.items.filter(i=>i.id!==Number(id));state.sandbox.items.forEach(i=>{if(i.mountedId===Number(id))i.mountedId=null;});closeInlinePanel();save();render();},
 'burette-load':id=>buretteLoad(id),
 'bottle-dose':id=>{const item=apparatusItem(id);toast(directBenchDose(item?.loadedId));save();render();},
 'apparatus-detach':id=>{checkpoint();detachLabObject(state,'apparatus',Number(id),true);save();render();},
 'burette-dose':token=>{const [id,ml]=token.split(':'),item=apparatusItem(id),amount=Number(ml);if(!item?.loadedId||amount>item.remainingMl+1e-9)throw Error('Refill the burette before dispensing this volume.');const receiver=state.vessels.find(v=>v.id===item.targetId)||nearestVessel(state,item);if(!receiver)throw Error('Connect a receiving vessel or position one below the burette.');if(receiver.volume+amount>receiver.capacity)throw Error('The receiving vessel would overflow.');checkpoint();dose(receiver,chemicals.find(c=>c.id===item.loadedId),amount,item.concentration,elements);item.targetId=receiver.id;item.remainingMl=Math.max(0,item.remainingMl-amount);item.deliveredMl+=amount;state.selected=receiver.id;save();render();},
 'funnel-filter':id=>{const item=apparatusItem(id),source=state.vessels.find(v=>v.id===item?.sourceId),receiver=state.vessels.find(v=>v.id===item?.targetId);if(!source||!receiver){apparatusConnect(id);return;}checkpoint();try{filterVessel(source,receiver);}catch(e){undo.pop();throw e;}save();render();toast('Filtrate collected in '+receiver.name+'. Solid residue stays in '+source.name+'.');},
 'stand-mount':id=>{const item=apparatusItem(id),burettes=state.sandbox.items.filter(i=>i.kind==='burette');if(!burettes.length)throw Error('Add a burette first.');formModal('Mount a burette',`<div class="field"><label for="mounted">Burette</label><select id="mounted" name="mounted">${burettes.map(b=>`<option value="${b.id}">Burette ${b.id}</option>`).join('')}</select></div>`,form=>{const held=apparatusItem(form.get('mounted'));checkpoint();if(!commitLabSnap(state,'apparatus',held.id,{kind:'attach',x:item.x+80,y:item.y+10,role:'clamp',parent:'a:'+item.id,child:'a:'+held.id}))throw Error('Move the stand away from the edge to leave room for its apparatus.');});},
 'stopwatch-reset':id=>{const item=apparatusItem(id);checkpoint();item.elapsed=0;save();render();},
 'zoom-in':()=>{const v=$('#sandbox-viewport');zoomSandbox(state,1.15,v?.clientWidth||600,v?.clientHeight||650);save();render();},
 'zoom-out':()=>{const v=$('#sandbox-viewport');zoomSandbox(state,1/1.15,v?.clientWidth||600,v?.clientHeight||650);save();render();},
 'sandbox-home':()=>{const v=$('#sandbox-viewport');fitSandbox(state,v?.clientWidth||600,v?.clientHeight||650);save();render();},
 'clear-bench':()=>{checkpoint();state.vessels=[];state.sandbox=newSandbox();state.selected=null;state.nextVessel=1;save();render();},
 'sandbox-help':()=>modal('A bench you can make your own',`<p><b>Place:</b> drag glassware or apparatus from the shelf. Drop a reagent in empty space to place a bottle; drag it over a vessel to add a measured dose.</p><p><b>Arrange:</b> drag any object. Drag the empty canvas to pan; use + and − to zoom. Focus an object and use arrow keys for precise placement; Shift+Enter snaps or pours at a compatible target, and Escape detaches it. Use the wheel to zoom at the pointer.</p><p><b>Connect:</b> bring a thermometer, funnel or gas syringe to a vessel; place a vessel above a burner or on a balance. Burettes snap into stand clamps; receivers fit under their taps. A marker shows a compatible connection before release.</p><p><b>Measure:</b> fill a burette and deliver 0.1, 1 or 5 mL. Link a filter funnel to separate a source into a receiving vessel. Start and pause the stopwatch.</p><p><b>Observe:</b> supported reactions resolve on addition. Burners heat at 3°C per lab second. Gas volumes, mass readings and temperatures use the same chemistry inventory as the inspector.</p><p>All chemistry model boundaries still apply. Connections use geometric attachment points; the app does not calculate gas pressure, boil organic mixtures or simulate every apparatus configuration.</p>`)
});

document.addEventListener('click',e=>{const btn=e.target.closest('[data-act]');if(btn&&!btn.disabled){try{actions[btn.dataset.act]?.(btn.dataset.id);}catch(e){toast(e.message);}}});
document.addEventListener('change',e=>{if(e.target.dataset?.doseSetting){const key=e.target.dataset.doseSetting,value=Number(e.target.value),limits={volume:[.001,500],mass:[.001,100],concentration:[.001,2],transfer:[.1,100]};if(limits[key]&&Number.isFinite(value)&&value>=limits[key][0]&&value<=limits[key][1]){state.sandbox.dosing[key]=value;save();}else{e.target.value=state.sandbox.dosing[key];toast('Enter a value within the displayed range.');}}if(e.target.id==='motion'){state.motion=e.target.checked;save();applySettings();}});
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1500000)throw Error('Workspace files must be under 1.5 MB.');const candidate=validate(JSON.parse(await file.text()));formModal('Restore this workspace',`<p>Replace this device’s workspace with ${candidate.vessels.length} vessels and ${candidate.notes.length} notebook entries? Export the current workspace first if you want to keep it.</p>`,()=>{state=candidate;undo=[];page='bench';save();});}catch(e){toast('Could not import: '+e.message);}e.target.value='';};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog.open){e.preventDefault();closeInlinePanel();(page==='bench'?$('#sandbox-viewport'):main)?.focus();return;}if(e.key==='?'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();actions.help();}});
function route(){const [p,id]=location.hash.slice(1).split('/');if(NAV.some(([n])=>n===p)){page=p;practicalID=p==='practicals'&&practicals.some(x=>x.id===id)?id:null;quiz=null;render();}}
window.addEventListener('hashchange',route);applySettings();route();render();

let activeProfile=null;
startAuth({onUser:(user,options={})=>{
 if(options.error){toast(options.error);return;}
 if(options.logout){save();activeProfile=null;KEY='chemlab.studio.v2';state=fresh();undo=[];page='bench';render();}
 else if(user&&activeProfile!==user.username.toLowerCase()){
  activeProfile=user.username.toLowerCase();KEY='chemlab.studio.v2:'+activeProfile;
  try{const saved=localStorage.getItem(KEY);state=saved?validate(JSON.parse(saved)):fresh();}catch{state=fresh();toast('The saved workspace could not be restored. Import a backup if needed.');}
  undo=[];noteID=state.notes[0]?.id;page='bench';render();
 }
 const button=$('#account-button');if(button){button.textContent=user?'Sign out':'Sign in';button.title=user?'Signed in as '+user.username:'Chemlab account';}
 const avatar=$('.avatar');if(avatar){avatar.textContent=user?user.username[0].toUpperCase():'C';avatar.title=user?user.username:'Offline learner';}
}});
if(typeof setInterval==='function')setInterval(()=>{
 if(document.body.classList.contains('auth-locked'))return;
 if(tickSandbox(state,1)){save();if(page==='bench'&&!dialog.open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#sandbox-viewport')?.classList.contains('is-dragging'))render();}
},1000);

function renderMeasurementControls(){
 const d=state.sandbox.dosing;
 $('#measurement-controls').innerHTML=`<div class="mini-label">Measured additions</div><div class="bench-measures">${[['volume','Liquid / mL',.001,500],['mass','Solid / g',.001,100],['concentration','Concentration / mol dm⁻³',.001,2],['transfer','Pour mixture / %',.1,100]].map(([key,label,min,max])=>`<label>${label}<input type="number" id="bench-${key}" data-dose-setting="${key}" value="${d[key]}" min="${min}" max="${max}" step="any"></label>`).join('')}</div><p class="hint">Set a dose here. Drag a bottle over a vessel to add it. Drag liquid mixtures over another vessel to pour.</p>`;
}
function directBenchDose(reagentId,vesselId=selected()?.id,record=true){
 const c=chemicals.find(c=>c.id===reagentId),v=state.vessels.find(v=>v.id===vesselId);if(!c||!v)throw Error('Place a receiving vessel first.');
 const d=state.sandbox.dosing,amount=c.category==='indicator'?.1:c.state==='solid'?d.mass:c.state==='gas'?d.gas:d.volume;
 if(record)checkpoint();try{dose(v,c,amount,d.concentration,elements);}catch(error){if(record)undo.pop();throw error;}
 state.selected=v.id;state.sandbox.selectedItem=null;return `${fmt(amount)} ${c.state==='solid'?'g':'mL'} ${c.name} added to ${v.name}.`;
}
function directBuretteFill(item,reagentId,record=true,refresh=true){
 const c=chemicals.find(c=>c.id===reagentId);if(!item||item.kind!=='burette'||!c||!(c.state==='aqueous'&&c.category!=='indicator'||c.id==='water'))throw Error('Fill a burette with an aqueous solution or water.');
 if(record)checkpoint();item.loadedId=c.id;item.remainingMl=50;item.deliveredMl=0;item.concentration=state.sandbox.dosing.concentration;
 state.sandbox.selectedItem=item.id;if(refresh){save();render();}toast(`Burette filled with 50 mL ${c.name}.`);
}
function applyDirectDrop(snap){
 if(snap.kind==='fill'){const bottle=apparatusItem(snap.bottleId);directBuretteFill(apparatusItem(snap.itemId),bottle?.loadedId,false,false);}
 if(snap.kind==='dose'){const item=apparatusItem(snap.itemId);toast(directBenchDose(item?.loadedId,snap.vesselId,false));}
 if(snap.kind==='pour'||snap.kind==='filter'){
  const source=state.vessels.find(v=>v.id===snap.sourceId),receiver=state.vessels.find(v=>v.id===snap.vesselId);if(!source||!receiver||source===receiver)throw Error('Use two different vessels.');
  if(snap.kind==='filter'){filterVessel(source,receiver);const funnel=apparatusItem(snap.itemId);if(funnel)funnel.sourceId=source.id;}
  else transfer(source,receiver,state.sandbox.dosing.transfer);
  state.selected=receiver.id;state.sandbox.selectedItem=null;toast(snap.kind==='filter'?'Filtrate collected; residue stays in the source.':`${fmt(state.sandbox.dosing.transfer)}% of the mixture poured into ${receiver.name}.`);
 }
}
function renderApparatusInspector(item){
 const kind=item.kind,v=state.vessels.find(v=>v.id===item.targetId),c=chemicals.find(c=>c.id===item.loadedId);
 const tips={burner:'Drag a vessel above the flame until the snap marker appears. Light or extinguish the burner with its on-bench control.',burette:'Drag into a stand clamp, then place a receiver below its tap. Drop a solution from the library onto the burette to fill it.',syringe:'Bring the syringe beside a gas-producing vessel to connect its delivery tube.',funnel:'Fit the funnel into a receiving vessel. Drag a mixture above the funnel to filter it.',thermometer:'Drag the bulb into a vessel to read its live temperature.',balance:'Place a vessel on the weighing pan. The reading includes the solid portion of the sample.',stand:'Bring a burette close to the clamp. Move the stand to carry the assembled equipment.',stopwatch:'Start, pause and reset directly on the bench.',bottle:'Drag this bottle over a vessel. The measured addition uses the settings above.'};
 $('#inspector').innerHTML=`<div class="apparatus-details"><div class="mini-label">${esc(kind==='bottle'?c?.name||'Reagent bottle':apparatusKinds[kind].name)}</div><p class="hint">${tips[kind]}</p>${v?`<p class="connection-readout">Connected · ${esc(v.name)}</p>`:''}<div class="row wrap inspector-actions">${['burner','stopwatch'].includes(kind)?`<button class="btn small" data-act="apparatus-toggle" data-id="${item.id}">${item.on?'Pause / switch off':kind==='burner'?'Light burner':'Start timer'}</button>`:''}${kind==='stopwatch'?`<button class="btn small" data-act="stopwatch-reset" data-id="${item.id}">Reset timer</button>`:''}${kind==='burette'?`<p class="hint">${esc(c?.name||'Empty')} · ${fmt(item.remainingMl)} mL remaining · ${fmt(item.deliveredMl)} mL delivered</p><button class="btn small" data-act="burette-load" data-id="${item.id}">Adjust filling</button>${[.1,1,5].map(ml=>`<button class="btn small" data-act="burette-dose" data-id="${item.id}:${ml}">${ml} mL</button>`).join('')}`:''}${kind==='bottle'?`<button class="btn small" data-act="bottle-dose" data-id="${item.id}">Add to selected vessel</button>`:''}${!['bottle','stand','stopwatch'].includes(kind)?`<button class="btn small" data-act="apparatus-connect" data-id="${item.id}">Snap to a vessel…</button>`:''}${kind==='stand'?`<button class="btn small" data-act="stand-mount" data-id="${item.id}">Choose burette…</button>`:''}<button class="btn small" data-act="apparatus-detach" data-id="${item.id}">Detach</button><button class="btn small danger" data-act="apparatus-remove" data-id="${item.id}">Remove</button></div></div>`;
}
function attachApparatusToVessel(item,v){
 const k=item.kind,a='a:'+item.id,b='v:'+v.id;
 const rules={burner:{x:v.x+30,y:v.y+178,role:'heat',parent:a,child:b},balance:{x:v.x,y:v.y+150,role:'weigh',parent:a,child:b},burette:{x:v.x+37,y:v.y-245,role:'receiver',parent:a,child:b},thermometer:{x:v.x+45,y:v.y+10,role:'probe',parent:b,child:a},funnel:{x:v.x+28,y:v.y-118,role:'funnel',parent:b,child:a},syringe:{x:v.x+160,y:v.y-50,role:'gas',parent:b,child:a}};
 const rule=rules[k];if(!rule)throw Error('This apparatus does not attach to a vessel.');
 const dx=rule.x<0?-rule.x:rule.x>1440?1440-rule.x:0,dy=rule.y<0?-rule.y:rule.y>760?760-rule.y:0;
 if(dx||dy){const ox=v.x,oy=v.y;moveLabObject(state,'vessel',v.id,v.x+dx,v.y+dy);rule.x+=v.x-ox;rule.y+=v.y-oy;}
 if(!commitLabSnap(state,'apparatus',item.id,{kind:'attach',...rule}))throw Error('Detach the existing assembly before making this connection.');
}
